     1	/**
     2	 * Everything the plugin decides, with nothing from the SDK in it.
     3	 *
     4	 * A key face is a function of what the plugin knows: whether it is
     5	 * signed in, whether its socket is open, which runs are held, which is
     6	 * pinned, and what that run last published. `reduce` moves the state on
     7	 * one event at a time; the `*Face` functions read it. Keeping them pure
     8	 * is what lets the twelve states a key can be in have a test each.
     9	 */
    10	
    11	/**
    12	 * What a deck may press, right now, in the pack's own words.
    13	 *
    14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
    15	 * from `apps/web`, so this shape is mirrored rather than shared.
    16	 */
    17	export interface Offer {
    18	  seq: number;
    19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
    20	  moves: Array<{ id: string; label: string }>;
    21	  undo: { what: string } | null;
    22	  /** Why a deck cannot press this, in words a key face can carry. */
    23	  needsPage: string | null;
    24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
    25	}
    26	
    27	export type SessionState = "none" | "expired" | "ok";
    28	export type SocketState = "closed" | "connecting" | "open";
    29	export interface HeldRun {
    30	  id: string;
    31	  name?: string;
    32	  packTitle?: string;
    33	}
    34	export interface Snapshot {
    35	  unit?: number;
    36	  words?: { unit: string };
    37	  score?: { text: string };
    38	  latest?: { text: string } | null;
    39	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
    40	  standings?: Array<{ name: string; points: number; place: number }>;
    41	  counters?: Array<{ id: string; label: string; value: number }>;
    42	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
    43	  at?: string;
    44	  offer?: Offer;
    45	}
    46	export interface DeckState {
    47	  session: SessionState;
    48	  /** Whether the streamer has switched the deck on. No socket while false. */
    49	  on: boolean;
    50	  /** Whether the last time it went off, it was the idle timer rather than a press. */
    51	  idleOff: boolean;
    52	  socket: SocketState;
    53	  runs: HeldRun[];
    54	  any: boolean;
    55	  pinned: string | null;
    56	  attached: string | null;
    57	  snapshot: Snapshot | null;
    58	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
    59	}
    60	export type Tone = "live" | "dim" | "refuse";
    61	export interface Face {
    62	  title: string;
    63	  tone: Tone;
    64	  when?: string;
    65	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
    66	  fraction?: number;
    67	}
    68	export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
    69	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
    70	export type DeckEvent =
    71	  | { t: "session"; state: SessionState }
    72	  | { t: "on"; on: boolean; idle?: boolean }
    73	  | { t: "socket"; state: SocketState }
    74	  | { t: "runs"; runs: HeldRun[]; any: boolean }
    75	  | { t: "pin"; id: string | null }
    76	  | { t: "snapshot"; snapshot: Snapshot }
    77	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
    78	  | { t: "tick" };
    79	
    80	const FLASH_MS = 3000;
    81	
    82	/** How long a connection that is holding nothing waits before closing itself. */
    83	export const IDLE_OFF_MS = 30 * 60_000;
    84	
    85	export function initial(): DeckState {
    86	  return {
    87	    session: "none",
    88	    on: false,
    89	    idleOff: false,
    90	    socket: "closed",
    91	    runs: [],
    92	    any: false,
    93	    pinned: null,
    94	    attached: null,
    95	    snapshot: null,
    96	    flash: null,
    97	  };
    98	}
    99	
   100	export function attachedRun(state: DeckState): string | null {
   101	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
   102	  return state.runs.length === 1 ? state.runs[0]!.id : null;
   103	}
   104	
   105	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
   106	  switch (event.t) {
   107	    case "session":
   108	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
   109	    case "on":
   110	      // Going off is a full stop: no socket, nothing held, nothing to draw
   111	      // a number from. The pin is a preference, not a holding, and stays.
   112	      return event.on
   113	        ? { ...state, on: true, idleOff: false }
   114	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
   115	    case "socket":
   116	      return event.state === "open"
   117	        ? { ...state, socket: "open" }
   118	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
   119	    case "runs": {
   120	      const next = { ...state, runs: event.runs, any: event.any };
   121	      const attached = attachedRun(next);
   122	      // A run that went away takes its numbers with it; a run that is
   123	      // still here keeps them until the next snapshot lands.
   124	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
   125	    }
   126	    case "pin": {
   127	      const next = { ...state, pinned: event.id };
   128	      const attached = attachedRun(next);
   129	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
   130	    }
   131	    case "snapshot":
   132	      return { ...state, snapshot: event.snapshot };
   133	    case "drove": {
   134	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
   135	      // A `drove` verdict is the freshest seq source: the next press
   136	      // should not carry a seq gone stale while it was in flight.
   137	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
   138	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
   139	    }
   140	    case "tick": {
   141	      const expired = state.flash !== null && state.flash.until <= now;
   142	      // Controller ruling 3: a dial redraws every second while a clock is
   143	      // running, so its remaining time keeps moving between snapshots. An
   144	      // idle deck has nothing that changes on the tick, so it stays the
   145	      // same object and nothing redraws.
   146	      const running = state.snapshot?.clocks?.some((c) => c.status === "running") ?? false;
   147	      if (!expired && !running) return state;
   148	      return expired ? { ...state, flash: null } : { ...state };
   149	    }
   150	  }
   151	}
   152	
   153	/** What a key says about the run once the deck is signed in and switched on. */
   154	function held(state: DeckState): Face | null {
   155	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
   156	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
   157	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
   158	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
   159	  return null;
   160	}
   161	
   162	/** The state every key shares before any of them has something of its own to say. */
   163	function common(state: DeckState): Face | null {
   164	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
   165	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
   166	  // A key that depends on the connection says to make it first: the state
   167	  // on top, the thing to do about it beneath.
   168	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
   169	  return held(state);
   170	}
   171	
   172	/** The run a deck is following, named, or nothing. */
   173	function attachedName(state: DeckState): Face | null {
   174	  const run = state.runs.find((r) => r.id === state.attached);
   175	  if (!run) return null;
   176	  return { title: run.name ?? run.packTitle ?? run.id, tone: "live", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
   177	}
   178	
   179	/**
   180	 * The Connect key, which reports the connection rather than the run behind it.
   181	 *
   182	 * It is the one key that has something to say while the deck is off, so it
   183	 * skips the "Not connected" every other key stops at and names the state it
   184	 * is actually in - down by choice, down by the idle timer, or on its way up.
   185	 */
   186	export function connectFace(state: DeckState): Face {
   187	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
   188	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
   189	  if (!state.on) return state.idleOff ? { title: "Idle · press to connect", tone: "dim" } : { title: "Offline", tone: "dim" };
   190	  if (state.socket === "connecting") return { title: "Connecting", tone: "dim" };
   191	  return held(state) ?? attachedName(state) ?? { title: "Connected", tone: "live" };
   192	}
   193	
   194	/**
   195	 * When a connection that is holding nothing should close itself.
   196	 *
   197	 * `since` is when it last had nothing to follow. Null means the clock is not
   198	 * running at all - a deck following a live run never times out, however long
   199	 * the stream goes, and a deck that is off or still dialing has nothing to
   200	 * give up on.
   201	 */
   202	export function idleDeadline(state: DeckState, since: number): number | null {
   203	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
   204	  return since + IDLE_OFF_MS;
   205	}
   206	
   207	function flashed(state: DeckState): Face | null {
   208	  if (!state.flash || state.flash.ok) return null;
   209	  return { title: state.flash.say ?? "No", tone: "refuse" };
   210	}
   211	
   212	export function nextFace(state: DeckState): Face {
   213	  const c = common(state) ?? flashed(state);
   214	  if (c) return c;
   215	  const offer = state.snapshot?.offer;
   216	  if (!offer) return { title: "Loading…", tone: "dim" };
   217	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
   218	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
   219	}
   220	
   221	export function pressFace(state: DeckState, target: PressTarget): Face {
   222	  const c = common(state) ?? flashed(state);
   223	  if (c) return c;
   224	  const offer = state.snapshot?.offer;
   225	  if (!offer) return { title: "Loading…", tone: "dim" };
   226	  if (target.kind === "roll")
   227	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
   228	  if (target.kind === "move") {
   229	    const m = offer.moves.find((x) => x.id === target.id);
   230	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
   231	  }
   232	  const p = offer.presets.find((x) => x.kind === target.preset);
   233	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
   234	}
   235	
   236	export function undoFace(state: DeckState): Face {
   237	  const c = common(state) ?? flashed(state);
   238	  if (c) return c;
   239	  const undo = state.snapshot?.offer?.undo;
   240	  return undo ? { title: "Undo", tone: "live", when: undo.what } : { title: "Nothing to undo", tone: "dim" };
   241	}
   242	
   243	export function runFace(state: DeckState): Face {
   244	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
   245	}
   246	
   247	/** How far a clock has moved since the snapshot that reported it, in ms. */
   248	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
   249	  const since = c.status === "running" ? now - Date.parse(at) : 0;
   250	  return c.elapsedMs + since;
   251	}
   252	
   253	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
   254	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
   255	  const elapsed = clockElapsedMs(c, at, now);
   256	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
   257	  const s = Math.floor(ms / 1000);
   258	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
   259	}
   260	
   261	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
   262	  const c = common(state);
   263	  if (c) return c;
   264	  const snap = state.snapshot;
   265	  if (!snap) return { title: "Loading…", tone: "dim" };
   266	  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
   267	  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
   268	  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
   269	  if (field === "leader") {
   270	    const top = snap.standings?.[0];
   271	    return top ? { title: top.name, tone: "live", when: `${top.points} pts` } : { title: "—", tone: "dim", when: "Leader" };
   272	  }
   273	  if (field === "clock") {
   274	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
   275	    if (!clock || !snap.at) return { title: "—", tone: "dim", when: "Clock" };
   276	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
   277	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
   278	    return { title: clockText(clock, snap.at, now), tone: "live", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
   279	  }
   280	  if ("counter" in field) {
   281	    const x = snap.counters?.find((k) => k.id === field.counter);
   282	    return x ? { title: String(x.value), tone: "live", when: x.label } : { title: "—", tone: "dim" };
   283	  }
   284	  const r = snap.resources?.find((k) => k.id === field.resource);
   285	  return r ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "live", when: r.label } : { title: "—", tone: "dim" };
   286	}
=== src/face.ts ===
     1	import type { Face, Tone } from "./state";
     2	
     3	/**
     4	 * A key face as SVG.
     5	 *
     6	 * SVG, because it needs no rasterizer and no native module in a package
     7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
     8	 * rejects a raw SVG string despite the documentation. 144 square is the
     9	 * @2x size; the software scales it to any key.
    10	 *
    11	 * The palette is the app's own: celadon for a live key, kiln for a
    12	 * refusal, the muted ink for a key with nothing to do. System sans, since
    13	 * a font in an SVG would have to travel as base64 on every redraw.
    14	 */
    15	const TONE: Record<Tone, { ground: string; ink: string; edge: string }> = {
    16	  live: { ground: "#1e2f27", ink: "#e7eae6", edge: "#8cc3a6" },
    17	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733" },
    18	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
    19	};
    20	
    21	const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    22	
    23	/**
    24	 * Greedy word wrap: pack words onto a line up to `width` characters, at
    25	 * most `lines` lines. A word too long for a fresh line is cut rather than
    26	 * looped over. The last line gets an ellipsis if any text was dropped -
    27	 * either words left unplaced or a word cut to fit.
    28	 */
    29	export function wrap(text: string, width = 10, lines = 3): string[] {
    30	  const words = text.split(/\s+/).filter(Boolean);
    31	  const out: string[] = [];
    32	  let i = 0;
    33	  let truncated = false;
    34	  while (i < words.length && out.length < lines) {
    35	    let line = words[i]!;
    36	    if (line.length > width) {
    37	      line = line.slice(0, width);
    38	      truncated = true;
    39	      i++;
    40	    } else {
    41	      i++;
    42	      while (i < words.length && (line + " " + words[i]).length <= width) {
    43	        line += " " + words[i];
    44	        i++;
    45	      }
    46	    }
    47	    out.push(line);
    48	  }
    49	  if (i < words.length) truncated = true;
    50	  if (truncated && out.length > 0) {
    51	    const last = out[out.length - 1]!;
    52	    out[out.length - 1] = last.length >= width ? last.slice(0, Math.max(0, width - 1)) + "…" : last + "…";
    53	  }
    54	  return out;
    55	}
    56	
    57	export function faceImage(face: Face): string {
    58	  const t = TONE[face.tone];
    59	  const lines = wrap(face.title);
    60	  const size = lines.length === 1 && face.title.length <= 6 ? 34 : 20;
    61	  const top = 72 - ((lines.length - 1) * size * 1.15) / 2 + (face.when ? -8 : 0);
    62	  const spans = lines.map((l, i) => `<tspan x="72" y="${(top + i * size * 1.15).toFixed(1)}">${esc(l)}</tspan>`).join("");
    63	  const when = face.when
    64	    ? `<text x="72" y="128" text-anchor="middle" font-size="12" fill="${t.edge}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(face.when.slice(0, 18))}</text>`
    65	    : "";
    66	  const svg =
    67	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
    68	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
    69	    // thing even when the drawn lines above cut it short.
    70	    `<title>${esc(face.title)}</title>` +
    71	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
    72	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="3"/>` +
    73	    `<text text-anchor="middle" dominant-baseline="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="system-ui, -apple-system, Segoe UI, sans-serif">${spans}</text>` +
    74	    when +
    75	    `</svg>`;
    76	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
    77	}

