   192	}
   193	
   194	/**
   195	 * When a connection that is holding nothing should close itself.
   196	 *
   197	 * `since` is when it last had nothing to follow. Null means the clock is not
   198	 * running at all - a deck following a live run never times out, however long
   199	 * the stream goes, and a deck that is off or still dialing has nothing to
   200	 * give up on.
   201	 */
   202	export function idleDeadline(state: DeckState, since: number): number | null {
   203	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
   204	  return since + IDLE_OFF_MS;
   205	}
   206	
   207	function flashed(state: DeckState): Face | null {
   208	  if (!state.flash || state.flash.ok) return null;
   209	  return { title: state.flash.say ?? "No", tone: "refuse" };
   210	}
   211	
   212	export function nextFace(state: DeckState): Face {
   213	  const c = common(state) ?? flashed(state);
   214	  if (c) return c;
   215	  const offer = state.snapshot?.offer;
   216	  if (!offer) return { title: "Loading…", tone: "dim" };
   217	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
   218	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
   219	}
   220	
   221	export function pressFace(state: DeckState, target: PressTarget): Face {
   222	  const c = common(state) ?? flashed(state);
   223	  if (c) return c;
   224	  const offer = state.snapshot?.offer;
   225	  if (!offer) return { title: "Loading…", tone: "dim" };
   226	  if (target.kind === "roll")
   227	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
   228	  if (target.kind === "move") {
   229	    const m = offer.moves.find((x) => x.id === target.id);
   230	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
   231	  }
   232	  const p = offer.presets.find((x) => x.kind === target.preset);
   233	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
   234	}
   235	
   236	export function undoFace(state: DeckState): Face {
   237	  const c = common(state) ?? flashed(state);
   238	  if (c) return c;
   239	  const undo = state.snapshot?.offer?.undo;
   240	  return undo ? { title: "Undo", tone: "live", when: undo.what } : { title: "Nothing to undo", tone: "dim" };
   241	}
   242	
   243	export function runFace(state: DeckState): Face {
   244	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
   245	}
   246	
   247	/** How far a clock has moved since the snapshot that reported it, in ms. */
   248	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
   249	  const since = c.status === "running" ? now - Date.parse(at) : 0;
   250	  return c.elapsedMs + since;
   251	}
   252	
   253	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
   254	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
   255	  const elapsed = clockElapsedMs(c, at, now);
   256	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
   257	  const s = Math.floor(ms / 1000);
   258	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
   259	}
   260	
   261	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
   262	  const c = common(state);
   263	  if (c) return c;
   264	  const snap = state.snapshot;
   265	  if (!snap) return { title: "Loading…", tone: "dim" };
   266	  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
   267	  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
   268	  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
   269	  if (field === "leader") {
   270	    const top = snap.standings?.[0];
   271	    return top ? { title: top.name, tone: "live", when: `${top.points} pts` } : { title: "—", tone: "dim", when: "Leader" };
   272	  }
   273	  if (field === "clock") {
   274	    const clock = snap.clocks?.find((x) => x.status === "running") ?? snap.clocks?.[0];
   275	    if (!clock || !snap.at) return { title: "—", tone: "dim", when: "Clock" };
   276	    const running = clock.kind === "timer" && clock.status === "running" && clock.seconds !== null;
   277	    const fraction = running ? clockElapsedMs(clock, snap.at, now) / (clock.seconds! * 1000) : undefined;
   278	    return { title: clockText(clock, snap.at, now), tone: "live", when: clock.label, ...(fraction !== undefined ? { fraction } : {}) };
   279	  }
   280	  if ("counter" in field) {
   281	    const x = snap.counters?.find((k) => k.id === field.counter);
   282	    return x ? { title: String(x.value), tone: "live", when: x.label } : { title: "—", tone: "dim" };
   283	  }
   284	  const r = snap.resources?.find((k) => k.id === field.resource);
   285	  return r ? { title: r.max === null ? String(r.value) : `${r.value}/${r.max}`, tone: "live", when: r.label } : { title: "—", tone: "dim" };
   286	}
