     1	import type { Face, Tone } from "./state";
     2	
     3	/**
     4	 * A key face as SVG.
     5	 *
     6	 * SVG, because it needs no rasterizer and no native module in a package
     7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
     8	 * rejects a raw SVG string despite the documentation. 144 square is the
     9	 * @2x size; the software scales it to any key.
    10	 *
    11	 * The palette is the app's own: celadon for a live key, kiln for a
    12	 * refusal, the muted ink for a key with nothing to do. System sans, since
    13	 * a font in an SVG would have to travel as base64 on every redraw.
    14	 */
    15	const TONE: Record<Tone, { ground: string; ink: string; edge: string }> = {
    16	  live: { ground: "#1e2f27", ink: "#e7eae6", edge: "#8cc3a6" },
    17	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733" },
    18	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
    19	};
    20	
    21	const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    22	
    23	/**
    24	 * Greedy word wrap: pack words onto a line up to `width` characters, at
    25	 * most `lines` lines. A word too long for a fresh line is cut rather than
    26	 * looped over. The last line gets an ellipsis if any text was dropped -
    27	 * either words left unplaced or a word cut to fit.
    28	 */
    29	export function wrap(text: string, width = 10, lines = 3): string[] {
    30	  const words = text.split(/\s+/).filter(Boolean);
    31	  const out: string[] = [];
    32	  let i = 0;
    33	  let truncated = false;
    34	  while (i < words.length && out.length < lines) {
    35	    let line = words[i]!;
    36	    if (line.length > width) {
    37	      line = line.slice(0, width);
    38	      truncated = true;
    39	      i++;
    40	    } else {
    41	      i++;
    42	      while (i < words.length && (line + " " + words[i]).length <= width) {
    43	        line += " " + words[i];
    44	        i++;
    45	      }
    46	    }
    47	    out.push(line);
    48	  }
    49	  if (i < words.length) truncated = true;
    50	  if (truncated && out.length > 0) {
    51	    const last = out[out.length - 1]!;
    52	    out[out.length - 1] = last.length >= width ? last.slice(0, Math.max(0, width - 1)) + "…" : last + "…";
    53	  }
    54	  return out;
    55	}
    56	
    57	export function faceImage(face: Face): string {
    58	  const t = TONE[face.tone];
    59	  const lines = wrap(face.title);
    60	  const size = lines.length === 1 && face.title.length <= 6 ? 34 : 20;
    61	  const top = 72 - ((lines.length - 1) * size * 1.15) / 2 + (face.when ? -8 : 0);
    62	  const spans = lines.map((l, i) => `<tspan x="72" y="${(top + i * size * 1.15).toFixed(1)}">${esc(l)}</tspan>`).join("");
    63	  const when = face.when
    64	    ? `<text x="72" y="128" text-anchor="middle" font-size="12" fill="${t.edge}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(face.when.slice(0, 18))}</text>`
    65	    : "";
    66	  const svg =
    67	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
    68	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
    69	    // thing even when the drawn lines above cut it short.
    70	    `<title>${esc(face.title)}</title>` +
    71	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
    72	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="3"/>` +
    73	    `<text text-anchor="middle" dominant-baseline="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="system-ui, -apple-system, Segoe UI, sans-serif">${spans}</text>` +
    74	    when +
    75	    `</svg>`;
    76	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
    77	}

