     9	} from "@elgato/streamdeck";
    10	
    11	import { faceImage } from "../face.ts";
    12	import { sayWho, store, wire } from "../plugin.ts";
    13	import type { DeckState, Face } from "../state.ts";
    14	
    15	/**
    16	 * The JSON shape Stream Deck persists, mirrored rather than imported.
    17	 *
    18	 * `SingletonAction` constrains its settings to `@elgato/utils`' `JsonObject`,
    19	 * which `@elgato/streamdeck` does not re-export; this is the same type,
    20	 * structurally, without depending on a package the plugin does not declare.
    21	 */
    22	type JsonPrimitive = boolean | number | string | null | undefined;
    23	type JsonValue = JsonObject | JsonPrimitive | JsonValue[];
    24	export type JsonObject = { [key: string]: JsonValue };
    25	
    26	/** How long a press waits for the server's verdict before giving up on it. */
    27	const VERDICT_MS = 5000;
    28	
    29	/** Either kind of placed action - a key on the grid, or a dial on a Stream Deck +. */
    30	export type Placed<S extends JsonObject> = DialAction<S> | KeyAction<S>;
    31	
    32	/**
    33	 * What every Runlog action has in common: one state, one wire, one drawing.
    34	 *
    35	 * A subclass says only what its face is. Redrawing is a subscription to the
    36	 * store held while any instance of the action is placed, so a key follows
    37	 * the run without knowing anything about the socket behind it.
    38	 */
    39	export abstract class RunlogAction<S extends JsonObject = JsonObject> extends SingletonAction<S> {
    40	  private unsub: (() => void) | null = null;
    41	  /** What each placement last said, so a change is logged once and a redraw that says the same thing is not. */
    42	  private said = new Map<string, string>();
    43	
    44	  /** What this action says, given everything the plugin knows. */
    45	  abstract face(state: DeckState, settings: S, now: number): Face;
    46	
    47	  override async onWillAppear(ev: WillAppearEvent<S>): Promise<void> {
    48	    this.unsub ??= store.subscribe(() => this.redrawAll());
    49	    const face = this.face(store.state, ev.payload.settings, Date.now());
    50	    // What a key came up saying, which is the only way to read the deck from
    51	    // a log. Once per placement, not once per redraw.
    52	    streamDeck.logger.info(`appeared: ${this.manifestId ?? "?"} says "${face.title}"`);
    53	    await this.draw(ev.action, ev.payload.settings);
    54	  }
    55	
    56	  override onWillDisappear(_ev: WillDisappearEvent<S>): void {
    57	    if (this.actions.length > 0) return;
    58	    this.unsub?.();
    59	    this.unsub = null;
    60	  }
    61	
    62	  /** A setting changed in the inspector redraws the key it was changed for. */
    63	  override async onDidReceiveSettings(ev: DidReceiveSettingsEvent<S>): Promise<void> {
    64	    await this.draw(ev.action, ev.payload.settings);
    65	  }
    66	
    67	  /** Every inspector carries the account block, so every inspector is told who is signed in. */
    68	  override async onPropertyInspectorDidAppear(): Promise<void> {
    69	    await sayWho();
    70	  }
    71	
    72	  protected async draw(action: Placed<S>, settings: S): Promise<void> {
    73	    const face = this.face(store.state, settings, Date.now());
    74	    if (this.said.get(action.id) !== face.title) {
    75	      this.said.set(action.id, face.title);
    76	      streamDeck.logger.info(`${this.manifestId ?? "?"} now says "${face.title}" for ${JSON.stringify(settings)}`);
    77	    }
    78	    if (action.isKey()) {
    79	      await action.setImage(faceImage(face));
    80	      await action.setTitle("");
    81	    } else if (action.isDial()) {
    82	      // The `$B1` layout's progress bar is the `indicator` key; it only
    83	      // has something to show for a running timer's fraction, controller
    84	      // ruling 4 - anything else leaves it out rather than drawing an
    85	      // empty bar.
    86	      const feedback: FeedbackPayload = { title: face.when ?? "", value: face.title };
    87	      if (face.fraction !== undefined) feedback.indicator = { value: Math.round(face.fraction * 100) };
    88	      await action.setFeedback(feedback);
    89	    }
    90	  }
    91	
    92	  private redrawAll(): void {
    93	    for (const a of this.actions) void a.getSettings<S>().then((s) => this.draw(a, s));
    94	  }
    95	
    96	  /**
    97	   * A press, with the flash the server's answer will turn into.
    98	   *
