    24	export type JsonObject = { [key: string]: JsonValue };
    25	
    26	/** How long a press waits for the server's verdict before giving up on it. */
    27	const VERDICT_MS = 5000;
    28	
    29	/** Either kind of placed action - a key on the grid, or a dial on a Stream Deck +. */
    30	export type Placed<S extends JsonObject> = DialAction<S> | KeyAction<S>;
    31	
    32	/**
    33	 * What every Runlog action has in common: one state, one wire, one drawing.
    34	 *
    35	 * A subclass says only what its face is. Redrawing is a subscription to the
    36	 * store held while any instance of the action is placed, so a key follows
    37	 * the run without knowing anything about the socket behind it.
    38	 */
