     1	import streamDeck from "@elgato/streamdeck";
     2	
     3	import { Connect } from "./actions/connect.ts";
     4	import { Metric } from "./actions/metric.ts";
     5	import { Next } from "./actions/next.ts";
     6	import { Press } from "./actions/press.ts";
     7	import { pin, Run, runsForInspector } from "./actions/run.ts";
     8	import { Undo } from "./actions/undo.ts";
     9	import { loadSession, normalizeBase, signIn, signOut, type Account } from "./session.ts";
    10	import { openWire } from "./socket.ts";
    11	import { makeStore } from "./store.ts";
    12	import { idleDeadline, type DeckState } from "./state.ts";
    13	
    14	/** Where Runlog lives when the streamer has not said otherwise. */
    15	const DEFAULT_API = "https://runlog.scrthq.com";
    16	
    17	/**
    18	 * What the plugin keeps between launches.
    19	 *
    20	 * The address and the pinned run, and nothing else: global settings are
    21	 * handed to the property inspector, which is a web view, so the session
    22	 * never comes near them. It lives in a file of the plugin's own.
    23	 */
    24	type Globals = { apiBase?: string; pinned?: string | null };
    25	
    26	let apiBase = DEFAULT_API;
    27	
    28	export const store = makeStore();
    29	export const wire = openWire((): Account => ({ apiBase }), store);
    30	
    31	/**
    32	 * The profile a deck is switched to once a run attaches.
    33	 *
    34	 * Not wired into the manifest yet: `streamdeck validate` refuses a
    35	 * `Profiles` entry without the `.streamDeckProfile` file behind it, and
    36	 * that file can only come from exporting the laid-out profile in the
    37	 * Stream Deck app. Once `profiles/Runlog.streamDeckProfile` exists, the
    38	 * manifest gains `Profiles: [{ Name: "Runlog", DeviceType: 0, Readonly: false, DontAutoSwitchWhenInstalled: true }]`.
    39	 * Until then the switch below fails quietly, which is correct for a copy
    40	 * without the profile.
    41	 */
    42	const PROFILE_NAME = "Runlog";
    43	
    44	/**
    45	 * Attaching switches the deck to the Runlog profile. It is the one
    46	 * attach feedback that works on every model, a six-key Mini included,
    47	 * and it puts the run's keys under the streamer's hand the moment a run
    48	 * starts. Only on a change from nothing to something: a snapshot landing
    49	 * is not a reason to yank the deck away from whatever it was showing.
    50	 */
    51	let wasAttached: string | null = null;
    52	store.subscribe((s) => {
    53	  if (s.attached && !wasAttached)
    54	    for (const d of streamDeck.devices) void streamDeck.profiles.switchToProfile(d.id, PROFILE_NAME).catch(() => {});
    55	  wasAttached = s.attached;
    56	});
    57	
    58	// The Run inspector's list is only as fresh as the last appear; a run
    59	// starting or ending while the picker is open moves it without the
    60	// streamer closing and reopening the page.
